const root = $input.first().json;
const body = root.body || {};
const data = body.data || {};
const msg = data.message || {};
const ctx =
  data.contextInfo ||
  msg.extendedTextMessage?.contextInfo ||
  msg.imageMessage?.contextInfo ||
  msg.videoMessage?.contextInfo ||
  msg.documentMessage?.contextInfo ||
  msg.audioMessage?.contextInfo ||
  {};

const quoted = ctx.quotedMessage || {};

function getTextFromMessage(m = {}) {
  return (
    m.conversation ||
    m.extendedTextMessage?.text ||
    m.imageMessage?.caption ||
    m.videoMessage?.caption ||
    m.documentMessage?.caption ||
    ""
  );
}

function detectMedia(m = {}) {
  if (m.imageMessage) {
    return {
      exists: true,
      source: null,
      type: "image",
      kind: "imageMessage",
      mimetype: m.imageMessage.mimetype || "image/jpeg",
      caption: m.imageMessage.caption || "",
      message: m.imageMessage,
    };
  }

  if (m.videoMessage) {
    const isGif = !!m.videoMessage.gifPlayback;
    return {
      exists: true,
      source: null,
      type: isGif ? "gif" : "video",
      kind: "videoMessage",
      mimetype: m.videoMessage.mimetype || "video/mp4",
      caption: m.videoMessage.caption || "",
      message: m.videoMessage,
    };
  }

  if (m.audioMessage) {
    return {
      exists: true,
      source: null,
      type: "audio",
      kind: "audioMessage",
      mimetype: m.audioMessage.mimetype || "audio/ogg",
      caption: "",
      message: m.audioMessage,
    };
  }

  if (m.documentMessage) {
    return {
      exists: true,
      source: null,
      type: "document",
      kind: "documentMessage",
      mimetype: m.documentMessage.mimetype || "application/octet-stream",
      caption: m.documentMessage.caption || "",
      fileName: m.documentMessage.fileName || "",
      message: m.documentMessage,
    };
  }

  if (m.stickerMessage) {
    return {
      exists: true,
      source: null,
      type: "sticker",
      kind: "stickerMessage",
      mimetype: m.stickerMessage.mimetype || "image/webp",
      caption: "",
      message: m.stickerMessage,
    };
  }

  return {
    exists: false,
    source: null,
    type: null,
    kind: null,
    mimetype: null,
    caption: "",
    message: null,
  };
}

const currentText = getTextFromMessage(msg).trim();
const quotedText = getTextFromMessage(quoted).trim();

const currentMedia = detectMedia(msg);
currentMedia.source = "current";

const quotedMedia = detectMedia(quoted);
quotedMedia.source = "quoted";

const selectedMedia = currentMedia.exists ? currentMedia : quotedMedia.exists ? quotedMedia : null;

const textLower = currentText.toLowerCase();

const isAskCommand = textLower.startsWith("/ask");
const isStickerCommand = textLower.startsWith("/stiker") || textLower.startsWith("/sticker");
const isNoteCmd = textLower.startsWith("/catat") || textLower.startsWith("/notes") || textLower.startsWith("/catatan");
const isExpenseCmd = textLower.startsWith("/expense") || textLower.startsWith("/pengeluaran");
const isDoneCmd = textLower.startsWith("/done") || textLower.startsWith("/selesai") || textLower.startsWith("/hapus-jadwal") || textLower.startsWith("/hapus");

const mentionedJid = ctx.mentionedJid || [];
const botLids = ["171619058196619", "195095164887244", "158613192614132", "6283130151476", "${$env.MY_WA_NUMBER}"];
const isMentionBot =
  botLids.some(b => b && currentText.includes("@" + b)) ||
  mentionedJid.some(j => botLids.some(b => b && j.includes(b))) ||
  textLower.includes("@n8n") ||
  textLower.includes("@bot") ||
  isNoteCmd ||
  isDoneCmd;

const quotedParticipant = ctx.participant || ctx.quotedMessageSender || "";
const isReplyingToBot = botLids.some(b => quotedParticipant.includes(b));

const isExpenseQuery = Boolean(/expense|pengeluaran|biaya|struk|nota|belanja|jajan/i.test(currentText) || isExpenseCmd);
const isNotesQuery = Boolean(/catat|notes|catatan|memo|utang|piutang/i.test(currentText) || isNoteCmd);
const isDoneOrDeleteQuery = Boolean(/selesai|done|beres|kelar|hapus jadwal|hapus agenda|batal/i.test(currentText) || isDoneCmd);
const hasImage = Boolean(selectedMedia?.type === "image");

const cleanText = currentText
  .replace(/@[a-zA-Z0-9_\-\.]+\s*/g, "")
  .replace(/^\/ask/i, "")
  .replace(/^\/stiker/i, "")
  .replace(/^\/sticker/i, "")
  .trim();

const remoteJid = data.key?.remoteJid || "";
const participant = data.key?.participant || data.key?.participantAlt || remoteJid;
const isGroup = remoteJid.endsWith("@g.us");
const isDevGroup = remoteJid === ($env.WA_GROUP_DEV || "120363336434287340@g.us");

const isManda = remoteJid.includes($env.MANDA_WA_NUMBER) || participant.includes($env.MANDA_WA_NUMBER);
const isOkta = Boolean(data.key?.fromMe) || remoteJid.includes($env.MY_WA_NUMBER) || participant.includes($env.MY_WA_NUMBER) || participant.includes("158613192614132");

// Deteksi Titip Pesan Dua Arah
const isTitipPesanToOkta = !isOkta && /titip|bilang|kasih tau|suruh|ingetin okta|sampaikan ke okta|pesan buat okta/i.test(currentText);
const isTitipPesanToManda = isOkta && /titip|bilang|kasih tau|suruh|ingetin manda|sampaikan ke manda|pesan buat manda/i.test(currentText);
const isTitipPesan = isTitipPesanToOkta || isTitipPesanToManda;
const titipTargetNumber = isTitipPesanToOkta ? $env.MY_WA_NUMBER : isTitipPesanToManda ? $env.MANDA_WA_NUMBER : null;
const titipTitle = isTitipPesanToOkta ? "💌 *Titip Pesan dari Kak Manda untuk Okta:*" : "💌 *Titip Pesan dari Okta untuk Kak Manda:*";

const hasAudio = selectedMedia?.type === "audio";

// Vision Query Detection
const isScheduleQuery = Boolean(hasAudio || isDoneOrDeleteQuery || /jadwal|agenda|kuliah|tugas|uas|kelas|acara|free|kosong|sibuk|kegiatan|besok|hari ini|lusa|ngapain|padet/i.test(currentText));
const isAnnouncementQuery = Boolean(/pengumuman|siam|berita kampus|info dosen|info kuliah|asinkron|dinas luar/i.test(currentText));
const isPresensiQuery = Boolean(/presensi|absen|absensi|kehadiran/i.test(currentText));

return [
  {
    json: {
      ...root,
      wa: {
        remoteJid,
        fromMe: data.key?.fromMe || false,
        messageId: data.key?.id || "",
        participant,
        participantAlt: data.key?.participantAlt || "",
        pushName: data.pushName || "",
        dateTime: new Date().toLocaleString("id-ID", {
          timeZone: "Asia/Jakarta",
          weekday: "long",
          year: "numeric",
          month: "long",
          day: "numeric",
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
          hour12: false
        }) + " WIB",
        dateTimeWib: new Date().toLocaleString("id-ID", {
          timeZone: "Asia/Jakarta",
          weekday: "long",
          year: "numeric",
          month: "long",
          day: "numeric",
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
          hour12: false
        }) + " WIB",
        dateTimeWita: new Date().toLocaleString("id-ID", {
          timeZone: "Asia/Makassar",
          weekday: "long",
          year: "numeric",
          month: "long",
          day: "numeric",
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
          hour12: false
        }) + " WITA",

        isManda,
        isOkta,
        isGroup,
        isDevGroup,

        currentText,
        quotedText,
        cleanText,

        isMentionBot,
        isReplyingToBot,
        isAskCommand,
        isStickerCommand,
        isTitipPesan,
        isTitipPesanToOkta,
        isTitipPesanToManda,
        titipTargetNumber,
        titipTitle,

        hasAudio,
        hasImage,
        isNotesQuery,
        isDoneOrDeleteQuery,
        isNoteCmd,
        isExpenseCmd,
        isExpenseQuery,
        isDoneCmd,
        isScheduleQuery,
        isAnnouncementQuery,
        isPresensiQuery,

        hasCurrentMedia: currentMedia.exists,
        hasQuotedMedia: quotedMedia.exists,
        hasAnyMedia: !!selectedMedia,

        currentMedia,
        quotedMedia,
        selectedMedia,

        selectedMediaSummary: selectedMedia
          ? `${selectedMedia.source} ${selectedMedia.type} (${selectedMedia.mimetype})`
          : "-",

        quotedPayload: {
          key: {
            remoteJid: data.key?.remoteJid,
            fromMe: data.key?.fromMe,
            id: data.key?.id,
            participant: data.key?.participant || data.participant,
          },
          message: data.message,
        },
      },
    },
  },
];

const items = $input.all();
let historyLines = [];

for (const item of items) {
  const row = item.json;
  if (!row || !row.role || !row.content) continue;

  const roleLabel = row.role === 'assistant' ? 'Asisten (Bot)' : (row.sender_name || 'User');

