      commandText = `/catat done ${detail || target}`;
    } else if (actionType === 'presensi') {
      commandText = `/presensi ${detail || 'hadir'}`;
    }

    actions.push({
      actionType,
      target,
      detail: detail || target,
      commandText
    });
  }
}

